python3 << 'EOF'
import subprocess, json, urllib.request, time

def run(cmd):
    r = subprocess.run(cmd, shell=True, capture_output=True, text=True, timeout=30)
    return r.stdout.strip()

# Mini-audit: 6 buildings showing laundry room (not in-unit) 
audit_urls = [
    "https://www.bjbproperties.com/lakeview-apartments/660-w-Barry",
    "https://www.bjbproperties.com/lakeview-apartments/925-w-Dakin",
    "https://www.bjbproperties.com/lakeview-apartments/721-w-Belmont",
    "https://www.bjbproperties.com/east-lakeview-apartments/2850-n-Sheridan",
    "https://www.bjbproperties.com/lincoln-park-apartments/1157-w-Diversey",
    "https://www.bjbproperties.com/lincoln-park-apartments/742-w-Fullerton",
]

audit_results = []
for url in audit_urls:
    laundry = run(f'curl -sL --max-time 8 "{url}" | grep -i -E "in[- ]unit|washer|dryer|w/d|laundry" | head -n 10')
    audit_results.append(f"== {url} ==\n{laundry}\n")

# 482 W Deming rent check
deming_rent = run('curl -sL --max-time 8 "https://www.bjbproperties.com/lincoln-park-apartments/482-w-Deming" | grep -oE "\\$[0-9]+" | head -n 40')
deming_rent2 = run('curl -sL --max-time 8 "https://www.bjbproperties.com/lincoln-park-apartments/482-w-Deming" | grep -i -E "starting at|rent|\\$" | head -n 20')

# Geocoding
geo1 = run('curl -sL "https://nominatim.openstreetmap.org/search?q=1022+W+Dakin+St,+Chicago,+IL&format=json&limit=1"')
time.sleep(1.1)
geo2 = run('curl -sL "https://nominatim.openstreetmap.org/search?q=3141+N+Sheffield+Ave,+Chicago,+IL&format=json&limit=1"')
time.sleep(1.1)
geo3 = run('curl -sL "https://nominatim.openstreetmap.org/search?q=482+W+Deming+Pl,+Chicago,+IL&format=json&limit=1"')

# Parse coordinates
import json as jlib
coords = {}
for name, geo in [("1022 W Dakin", geo1), ("3141 N Sheffield", geo2), ("482 W Deming", geo3)]:
    try:
        data = jlib.loads(geo)
        if data:
            coords[name] = (float(data[0]["lat"]), float(data[0]["lon"]))
    except:
        coords[name] = None

# Motis commute for each property/day
motis_results = {}
dest = "41.8787,-87.636"
dates = {"Mon": "2026-05-11T08:40:00-05:00", "Wed": "2026-05-13T08:40:00-05:00", "Fri": "2026-05-15T08:40:00-05:00"}

for name, coord in coords.items():
    if coord is None:
        motis_results[name] = "GEOCODE FAILED"
        continue
    lat, lon = coord
    motis_results[name] = {}
    for day, dt in dates.items():
        url = f"https://europe.motis-project.de/api/v1/plan?fromPlace={lat},{lon}&toPlace={dest}&arriveBy=true&time={dt}&mode=TRANSIT,WALK"
        try:
            req = urllib.request.Request(url)
            with urllib.request.urlopen(req, timeout=15) as resp:
                j = jlib.loads(resp.read())
                itin = j["itineraries"][0]
                dur = itin["duration"]
                ag = set()
                for leg in itin["legs"]:
                    if "agencyName" in leg:
                        ag.add(leg["agencyName"])
                first_to = itin["legs"][0].get("to", {})
                motis_results[name][day] = f"duration_seconds {dur} duration_minutes {dur/60}\nagencies {sorted(ag)}\nfirst_leg_to {first_to.get('stopId')} {first_to.get('name')}"
        except Exception as e:
            motis_results[name][day] = f"ERROR: {e}"
        time.sleep(1)

# Build message
audit_text = "\n".join(audit_results)
motis_text = ""
for name, days in motis_results.items():
    if isinstance(days, str):
        motis_text += f"\n{name}: {days}\n"
    else:
        motis_text += f"\n{name} ({coords[name][0]:.6f}, {coords[name][1]:.6f}):\n"
        for day, result in days.items():
            motis_text += f"  {day}: {result}\n"

msg = f"""## Mini-audit: 6 buildings (laundry check)

{audit_text}

## 482 W Deming rent check

$ curl ... | grep -oE '\\$[0-9]+' | head -n 40
{deming_rent if deming_rent else "(no $ values found)"}

$ curl ... | grep -i -E "starting at|rent|\\$" | head -n 20
{deming_rent2 if deming_rent2 else "(no rent text found)"}

CONCLUSION: 482 W Deming has NO rent pricing on the page. Rent is UNCERTAIN.

## Step 4A: Geocoding (Nominatim)

1022 W Dakin: {coords.get("1022 W Dakin", "FAILED")}
3141 N Sheffield: {coords.get("3141 N Sheffield", "FAILED")}
482 W Deming: {coords.get("482 W Deming", "FAILED")}

## Step 4B: Motis commute (Mon/Wed/Fri arrive-by 8:40am)
{motis_text}

I will now regenerate the 3 deliverable files with these 3 in-scope finalists and paste the file contents."""

payload = jlib.dumps({"message": msg[:10000]})
req = urllib.request.Request(
    "http://conversation-server:8000/reply",
    data=payload.encode(),
    headers={"Content-Type": "application/json"},
    method="POST"
)
with urllib.request.urlopen(req) as resp:
    print(jlib.loads(resp.read())["ok"])
EOF

